"""Network settings for all Hugging Face Hub traffic of the nightly sync job."""

import logging

import httpx2
from huggingface_hub import HfApi, set_client_factory
from huggingface_hub.utils._http import hf_request_event_hook

logger = logging.getLogger("app.network")

HUB_TIMEOUT = httpx2.Timeout(60.0, connect=5.0)
JOB_HEADERS = {"X-Acme-Job": "nightly-sync"}


class _HubClient(httpx2.Client):
    """Client whose timeouts cannot be switched off per request.

    huggingface_hub passes ``timeout=None`` explicitly (e.g. ``HfApi.model_info``), which httpx2 treats as
    "no timeout at all" instead of "use the client default". Map it back to the client default.
    """

    def build_request(self, *args, **kwargs) -> httpx2.Request:
        if kwargs.get("timeout", httpx2.USE_CLIENT_DEFAULT) is None:
            kwargs["timeout"] = httpx2.USE_CLIENT_DEFAULT
        return super().build_request(*args, **kwargs)


def configure_hub_http(transport=None) -> None:
    def client_factory() -> httpx2.Client:
        # Keep huggingface_hub's own defaults (request hook, redirects); request headers such as its
        # user agent are merged with the client headers by httpx2.
        return _HubClient(
            event_hooks={"request": [hf_request_event_hook]},
            follow_redirects=True,
            timeout=HUB_TIMEOUT,
            headers=JOB_HEADERS,
            transport=transport,
        )

    # Closes any existing shared client; the next request creates one from this factory.
    set_client_factory(client_factory)


def current_revision(repo_id: str) -> str | None:
    try:
        info = HfApi().model_info(repo_id, revision="main")
    except (httpx2.TimeoutException, httpx2.NetworkError) as e:
        logger.warning("Hugging Face Hub unreachable, cannot get revision of %s: %r", repo_id, e)
        return None
    return info.sha

